css
html, body {
  background-color: #000 !important;
}

/* Image de fond */
body::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:-2;

  background-image: url("https://pin.it/4NuqgLEXS");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;

  opacity: 0.35;           /* 0.25 - 0.55 */
  filter: saturate(1.1);  /* optionnel */
}

/* Overlay sombre pour garder la lisibilité */
body::after{
  content:"";
  position:fixed;
  inset:0;
  z-index:-1;
  background: rgba(0,0,0,0.55); /* 0.35 - 0.70 */
  pointer-events:none;
}

/* Améliore un peu la lisibilité selon les zones */
*{
  text-shadow: 0 1px 2px rgba(0,0,0,0.25);
}
